    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    INSERT INTO teachers (
        id, tenant_id, person_id, user_id, employee_number, first_name, middle_name, last_name, 
        preferred_name, display_name, profile_photo_url, date_of_birth, gender, preferred_language, 
