--
-- Name: fn_dev_login(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_dev_login(p_email character varying DEFAULT NULL::character varying) RETURNS TABLE(out_status character varying, out_user_id uuid, out_tenant_id uuid, out_effective_tenant_id uuid, out_active_org_id uuid, out_email character varying, out_display_name character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_target_email VARCHAR;
BEGIN
    IF p_email IS NOT NULL AND TRIM(p_email) <> '' THEN
        SELECT email INTO v_target_email 
        FROM users 
        WHERE LOWER(email) = LOWER(TRIM(p_email)) OR normalized_email = UPPER(TRIM(p_email)) 
        LIMIT 1;
    END IF;

    IF v_target_email IS NULL THEN
        SELECT email INTO v_target_email 
        FROM users 
        WHERE normalized_email = 'PRIYA@LITTLESTARS.COM' 
        LIMIT 1;
    END IF;

    IF v_target_email IS NULL THEN
        SELECT email INTO v_target_email 
        FROM users 
        ORDER BY created_at ASC 
        LIMIT 1;
    END IF;

    IF v_target_email IS NULL THEN
        RETURN QUERY SELECT 'no_users'::VARCHAR, NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR;
        RETURN;
    END IF;

    RETURN QUERY 
    SELECT * FROM fn_sync_external_login('DevLogin', v_target_email, v_target_email, 'Dev', 'User', NULL, 'Daycare');
END;
$$;


ALTER FUNCTION public.fn_dev_login(p_email character varying) OWNER TO postgres;

--
-- Name: fn_find_classroom_conflicts(uuid, uuid, date, time without time zone, time without time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_find_classroom_conflicts(p_tenant_id uuid, p_classroom_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_exclude_event_id uuid DEFAULT NULL::uuid) RETURNS TABLE(event_id uuid, title character varying, start_time time without time zone, end_time time without time zone, organizer_id uuid, organizer_name text)
    LANGUAGE sql STABLE
    AS $$
    SELECT e.id, e.title, e.start_time, e.end_time, e.organizer_id,
           COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''), u.email)::text
    FROM events e
    JOIN event_classrooms ec ON ec.event_id = e.id
    LEFT JOIN users u ON u.id = e.organizer_id
    WHERE e.tenant_id = p_tenant_id
      AND ec.classroom_id = p_classroom_id
      AND e.event_date = p_date
      AND e.status <> 'Cancelled'
      AND (p_exclude_event_id IS NULL OR e.id <> p_exclude_event_id)
      AND COALESCE(e.start_time, '00:00'::time) < COALESCE(p_end, '23:59:59.999999'::time)
      AND COALESCE(e.end_time, '23:59:59.999999'::time) > COALESCE(p_start, '00:00'::time)
    ORDER BY e.start_time NULLS FIRST;
$$;


ALTER FUNCTION public.fn_find_classroom_conflicts(p_tenant_id uuid, p_classroom_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_exclude_event_id uuid) OWNER TO postgres;

