        p_rest_status, p_toileting_activity, p_hygiene_type, p_comfort_mood,
        p_notes, p_parent_visible, p_recorded_by_user_id, p_recorded_by_name,
        p_correction_reason, p_is_corrected, p_created_at, p_updated_at
    );
END;
