--
-- Name: sp_dispatch_teacher_to_classroom(uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_dispatch_teacher_to_classroom(IN p_tenant_id uuid, IN p_classroom_id uuid, IN p_user_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_canonical_tenant_id uuid;
BEGIN
    SELECT tenant_id INTO v_canonical_tenant_id FROM classrooms WHERE id = p_classroom_id;
    IF v_canonical_tenant_id IS NULL THEN
        v_canonical_tenant_id := p_tenant_id;
    END IF;

    INSERT INTO classroom_teachers (id, tenant_id, classroom_id, user_id, is_primary)
    VALUES (gen_random_uuid(), v_canonical_tenant_id, p_classroom_id, p_user_id, FALSE)
    ON CONFLICT (classroom_id, user_id) DO UPDATE
    SET tenant_id = v_canonical_tenant_id;
END;
$$;


ALTER PROCEDURE public.sp_dispatch_teacher_to_classroom(IN p_tenant_id uuid, IN p_classroom_id uuid, IN p_user_id uuid) OWNER TO postgres;

--
-- Name: sp_end_child_nap_session(uuid, uuid, timestamp with time zone, integer, character varying, text, uuid, character varying); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.sp_end_child_nap_session(IN p_tenant_id uuid, IN p_session_id uuid, IN p_end_time timestamp with time zone, IN p_duration_minutes integer, IN p_outcome character varying, IN p_notes text, IN p_ended_by_user_id uuid, IN p_ended_by_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE child_nap_sessions
    SET end_time = p_end_time,
        duration_minutes = p_duration_minutes,
        status = 'Completed',
        outcome = p_outcome,
        notes = COALESCE(p_notes, notes),
        ended_by_user_id = p_ended_by_user_id,
        ended_by_name = p_ended_by_name,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = p_session_id AND tenant_id = p_tenant_id;
END;
$$;


