    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE parent_communications
    SET delivery_status = 'Read', updated_at = NOW()
    WHERE tenant_id = p_tenant_id
      AND child_id = p_child_id
      AND teacher_id = '00000000-0000-0000-0000-000000000000'
      AND delivery_status != 'Read';
END;
