    SET is_reversed = TRUE,
        status = 'Reversed',
        reversed_at = p_reversed_at,
        reversed_by = p_reversed_by,
        reversal_reason = p_reason,
        reversal_reference = p_reversal_reference
    WHERE id = p_payment_id;
END;
$$;


