eb3c7f91-97dd-416e-9df9-3649b2792a0b	60000000-0000-0000-0000-000000000003	4	Leaping Lily Pad Math Quest	Children decorate pre-folded leaping origami paper frogs and practice finger pressure control to make them leap across numbered lily pads.	{"AgeMax": 4, "AgeMin": 2, "Create": "A custom origami frog and a lily pad target course marked with numbers and colors.", "Together": "We decorate our paper frogs with colorful patterns and test how pressing the back of the frog makes it launch into the air.", "Challenge": "Can you make your paper frog jump from lily pad to lily pad to reach the big pond?", "Materials": ["Pre-cut square paper (green, yellow, light blue)", "Pre-folded paper jumping frogs", "Green foam or felt lily pads cutouts with numbers 1-5", "Washable markers", "Googly eyes and glue dots", "Large blue floor mat or blue fabric sheet"], "Reflection": "How did your frog move differently when you pressed softly compared to when you pressed hard?", "ChildChoice": "Children choose their frog color, decorative stickers, and which numbered path to leap along.", "Environment": "Indoor / Outdoor", "MagicMoment": "The exciting instant the paper frog launches into the air and lands right on a green lily pad.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Mastering the finger tap technique to send the paper frog leaping accurately onto a target.", "ExecutionGuide": {"Ask": "What happens when you press the back of the frog very quickly? Which lily pad is your frog aiming for next?", "Try": "If a child struggles to make the frog leap, place your finger over theirs to guide the downward slide release motion.", "Watch": "Observe how children adjust their finger pressure and fine motor precision when trying to launch the frog.", "Phases": [{"Name": "Frog Personalization", "ChildrenDo": "Decorate pre-folded paper frogs using markers, dots, and googly eyes.", "TeacherDoes": "Demonstrate how to stick googly eyes on the front and praise unique color choices.", "DurationMinutes": 8}, {"Name": "Launch Practice", "ChildrenDo": "Practice pressing down on the rear spring fold of the frog using one finger to make it launch.", "TeacherDoes": "Guide children's finger placement on the back fold. Model light versus firm pressure.", "DurationMinutes": 5}, {"Name": "Lily Pad Hop Game", "ChildrenDo": "Launch frogs along the numbered lily pad paths, calling out the numbers as frogs land on them.", "TeacherDoes": "Encourage children to aim for specific numbers and celebrate every successful jump.", "DurationMinutes": 10}, {"Name": "Tidy & Group Reflection", "ChildrenDo": "Gather paper frogs and collect lily pads into the storage basket.", "TeacherDoes": "Lead a brief cool-down transition chant about sleepy frogs resting in the pond.", "DurationMinutes": 2}], "Safety": ["Ensure children keep small googly eyes away from their mouths.", "Keep the jumping area clear of foot traffic to prevent tripping."], "Closing": "Place all the paper frogs together on the large center lily pad for a quick group photo before transition.", "Extensions": ["Add a tape measure to compare which frog jumped the longest distance.", "Introduce addition by adding up the numbers on the lily pads where the frog lands."], "Adaptations": ["Provide larger pre-folded frogs made of thick paper for children needing bigger motor targets.", "Draw visual directional arrows on the lily pads to assist visual learners."], "Preparation": ["Pre-fold 2-3 origami jumping frogs per child using sturdy cardstock or origami paper.", "Cut out 10-15 green felt circles to serve as lily pads and write numbers 1 to 5 on them.", "Spread the blue fabric sheet on the floor to represent the pond."], "MaterialSetup": ["Place blank origami frogs, markers, googly eyes, and glue dots at tables.", "Set the pre-folded blank frogs in small trays for easy access."], "EnvironmentSetup": ["Clear a wide floor space around the blue fabric pond.", "Arrange lily pads in linear paths leading toward the center of the pond."], "TeacherIntroduction": "Look at these amazing paper frogs! When we press down gently on their backs, they hop high into the air. Let's make our own frogs and help them leap across the lily pads!", "LittleMomentOpportunity": "A quiet moment occurs when a child gently places their finger on the frog, takes a focused breath, and watches it flip successfully.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Focus on the physical mechanics of pressing down on the spring-fold. Pre-fold the frogs so children can focus on decorating and playing without frustration.", "DevelopmentalGoals": []}	Draft Saved	a824798d-e5f4-444d-9fa6-76491e2be21d	2026-10-12 12:04:17.748015+00
2bd9a256-df24-4042-9be2-8bcbadec763c	60000000-0000-0000-0000-000000000004	2	Animal Adventure 1	Move, sound and imagine like animals.	{"AgeMax": 5, "AgeMin": 2, "Create": "", "Together": "", "Challenge": "", "Materials": [], "Reflection": "", "ChildChoice": "", "Environment": "Indoor / Outdoor", "MagicMoment": "", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "", "DevelopmentalGoals": []}	Draft Saved	a824798d-e5f4-444d-9fa6-76491e2be21d	2026-10-12 23:22:48.862029+00
893d23c7-f30f-44ca-b842-325ff37c06e0	60000000-0000-0000-0000-000000000004	3	Animal Adventure 1	Move, sound and imagine like animals.	{"AgeMax": 4, "AgeMin": 2, "Create": "", "Together": "", "Challenge": "", "Materials": [], "Reflection": "", "ChildChoice": "", "Environment": "Indoor / Outdoor", "MagicMoment": "", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "", "DevelopmentalGoals": []}	Draft Saved	a824798d-e5f4-444d-9fa6-76491e2be21d	2026-10-12 23:22:54.841548+00
dc381141-eba1-4454-b4fc-684b437f54d8	60000000-0000-0000-0000-000000000004	4	Mystery Box Sound Safari	Children pull an unseen animal toy from a mystery box and perform its sound for classmates to guess the identity.	{"AgeMax": 4, "AgeMin": 2, "Create": "An interactive guessing game experience based on vocal listening skills.", "Together": "Work together as a class to listen to clues, guess the animal, and validate each participant's performance.", "Challenge": "Can you imitate your animal's voice clearly enough for your classmates to guess which animal is in your hands?", "Materials": ["1 Mystery feel-box or opaque cloth bag", "12-15 diverse animal toys", "1 Toy magnifying glass or safari hat for the guessing leader"], "Reflection": "Which sound was the hardest to guess? How did you change your voice to sound like a big animal versus a tiny animal?", "ChildChoice": "Children pick an unseen toy from the mystery box and decide how to alter their pitch to match the animal.", "Environment": "Indoor / Outdoor", "MagicMoment": "The moment of surprise when a peer guesses the animal correctly based solely on the vocal imitation.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Successfully using vocal expression to communicate an identity to peers without using spoken words.", "ExecutionGuide": {"Ask": "Is that animal sound high-pitched like a bird or deep like an elephant?", "Try": "Suggest that a child try adding a movement along with the sound if their peers are struggling to guess.", "Watch": "Look for children who adjust their pitch (high for small animals, deep for large animals) to give better clues.", "Phases": [{"Name": "The Mystery Reveal", "ChildrenDo": "Reach into the bag without looking and grasp one animal figure.", "TeacherDoes": "Assist the child in keeping the toy hidden from view behind their back.", "DurationMinutes": 5}, {"Name": "Vocal Performance", "ChildrenDo": "Make the animal sound out loud while holding the toy out of sight.", "TeacherDoes": "Encourage full vocal engagement and give subtle hints if the sound is tricky.", "DurationMinutes": 10}, {"Name": "Peer Guessing & Reveal", "ChildrenDo": "Raise hands to guess the animal identity, then celebrate the reveal.", "TeacherDoes": "Call on guessers and prompt the performer to show the toy once guessed.", "DurationMinutes": 5}], "Safety": ["Ensure the mystery bag opening is smooth with no sharp edges.", "Sanitize toys before and after use."], "Closing": "Return all mystery animals to their bag for a quiet nap.", "Extensions": ["Create a sound chart matching drawings of animals to written descriptions of their sounds (e.g., 'Ribbit', 'Roar')."], "Adaptations": ["Allow children to show a small part of the toy if vocalization is difficult.", "Pair children together to perform a dual sound."], "Preparation": ["Place 12-15 animal toys inside the opaque bag.", "Set up a focused circle area on the rug."], "MaterialSetup": ["Place the closed mystery bag in the center of the semicircle within teacher reach."], "EnvironmentSetup": ["Dim ambient lighting slightly to enhance the mystery atmosphere.", "Gather children on the carpet in a semicircle."], "TeacherIntroduction": "Welcome Explorers! Deep inside this mystery bag are secret animals. We can only find out who they are by listening to their calls!", "LittleMomentOpportunity": "The proud smile on a child's face when the group instantly guesses their animal sound.", "SuggestedDurationMinutes": 20}, "TeacherGuidance": "Maintain excitement and mystery. Keep clues focused on vocal tone, pitch, and duration rather than visual hints.", "DevelopmentalGoals": []}	Draft Saved	a824798d-e5f4-444d-9fa6-76491e2be21d	2026-10-12 23:26:31.875785+00
620c4489-b708-4262-9ed0-d7cdf420bf60	60000000-0000-0000-0000-000000000004	5	Secret Safari Sound Parade	Children step into the role of Safari Sound Detectives, pulling secret animal performers from a mysterious safari trunk and enacting dramatic sound clues for their friends to decode before leading a hilarious group animal parade.	{"AgeMax": 4, "AgeMin": 2, "Create": "A dynamic pretend-play experience packed with dramatic vocal effects, animated guessing moments, and energetic group movement.", "Together": "Join forces as a detective crew to crack sound codes, celebrate each correct guess, and leap into action together for an enthusiastic group animal parade.", "Challenge": "Can you transform into a secret creature using vocal clues and dramatic body poses so your fellow sound detectives can guess who you are?", "Materials": ["1 Opaque 'Safari Trunk' (decorated box or soft fabric bag)", "12-15 Toy animals (mix of jungle, farm, and ocean creatures)", "1 Pair of toy paper-tube binoculars per child", "1 Playful Safari Ranger hat or badge for the leader"], "Reflection": "Which animal sound was the most fun to make? How did changing our voices make us feel like gigantic giants or tiny creatures?", "ChildChoice": "Children select their secret animal figure, choose their vocal pitch and volume, and decide on a custom action pose for the big reveal.", "Environment": "Indoor / Outdoor", "MagicMoment": "The burst of joy when a child reveals their mystery animal and the entire class instantly leaps up to mimic the sound and movement in unison.", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "Confidently expressing vocal creativity and leading peers in a collaborative, imaginative role-playing adventure.", "ExecutionGuide": {"Ask": "What kind of creature makes a squeaky, high sound like that? Can you show me how a giant creature walks across the jungle?", "Try": "Try inviting the whole group to repeat the sound together in a quiet whisper before making it as grand and loud as possible.", "Watch": "Watch for children using dramatic shifts in pitch, volume, and full-body postures to make their animal clues extra expressive.", "Phases": [{"Name": "Detective Briefing", "ChildrenDo": "Put on paper binoculars, practice deep roars and tiny squeaks, and listen to the activity rules.", "TeacherDoes": "Introduce the pretend safari world, model high and low sound effects, and present the Safari Trunk.", "DurationMinutes": 5}, {"Name": "Secret Sound Clues", "ChildrenDo": "Reach into the trunk without looking, freeze in a secret animal statue pose, and make expressive animal vocalizations.", "TeacherDoes": "Hand the performer the Ranger Badge, prompt fun sound variations, and call on detective peers to guess.", "DurationMinutes": 10}, {"Name": "Grand Safari Parade", "ChildrenDo": "Reveal the hidden toy figure, then jump up with the class to parade around the carpet making the animal sound.", "TeacherDoes": "Lead a celebratory 30-second mini-parade around the circle before returning to basecamp for the next turn.", "DurationMinutes": 10}], "Safety": ["Ensure carpet area is free of loose items during movement phases.", "Remind children to respect personal space while parading around the rug."], "Closing": "Guide all animals back into the Safari Trunk for a restful nap until the next expedition.", "Extensions": ["Create a Safari Sound Map where children draw paths to different animal habitats based on the sounds made during the activity."], "Adaptations": ["Allow shy children to perform alongside a designated 'Co-Ranger' buddy.", "Provide picture cue cards of animal sounds for children who benefit from visual support."], "Preparation": ["Place all toy animal figures inside the opaque Safari Trunk.", "Set out paper-tube binoculars at each spot on the rug.", "Put on the Safari Ranger hat to launch the pretend scenario."], "MaterialSetup": ["Place the closed Safari Trunk in the middle of the circle within easy reach."], "EnvironmentSetup": ["Arrange a open carpet circle called 'Safari Basecamp' with plenty of room for energetic group movement."], "TeacherIntroduction": "Calling all Safari Sound Detectives! Deep inside our magic trunk, secret animals are waiting to start a grand parade. Put on your binoculars and get ready to listen carefully!", "LittleMomentOpportunity": "The delighted giggles when the entire group simultaneously mimics a funny animal call during the parade reveal.", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "Keep the energy lively, dramatic, and upbeat! Set up a pretend 'Safari Basecamp' on the rug. Facilitate with playful enthusiasm, encouraging children to use dramatic facial expressions, vocal contrast, and expressive body movements.", "DevelopmentalGoals": []}	Draft Saved	a824798d-e5f4-444d-9fa6-76491e2be21d	2026-10-12 23:26:55.206206+00
ed90ab7e-705c-44e1-ae13-1d3586b4096e	60000000-0000-0000-0000-000000000001	1	Tiny Discoveries	Look closely at tiny things hiding in the classroom.	{"AgeMax": 5, "AgeMin": 2, "Create": "", "Together": "", "Challenge": "", "Materials": [], "Reflection": "", "ChildChoice": "", "Environment": "Indoor / Outdoor", "MagicMoment": "", "GroupSizeMax": 10, "GroupSizeMin": 4, "Accomplishment": "", "ExecutionGuide": {"Ask": "", "Try": "", "Watch": "", "Phases": [], "Safety": [], "Closing": "", "Extensions": [], "Adaptations": [], "Preparation": [], "MaterialSetup": [], "EnvironmentSetup": [], "TeacherIntroduction": "", "LittleMomentOpportunity": "", "SuggestedDurationMinutes": 25}, "TeacherGuidance": "", "DevelopmentalGoals": []}	Draft Saved	a824798d-e5f4-444d-9fa6-76491e2be21d	2026-10-15 00:05:51.225857+00
